(() => {
  'use strict';
  const KEY = 'mieayam_pos_demo_v1';
  const VERSION = 2;
  const root = document.body.dataset.root || './';
  const page = document.body.dataset.page || 'login';
  const now = new Date('2026-08-15T20:45:00+08:00');
  const uid = prefix => `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,6)}`;
  const rp = value => `Rp${Math.round(Number(value) || 0).toLocaleString('id-ID')}`;
  const esc = value => String(value ?? '').replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
  const initials = name => String(name || 'MN').split(' ').map(x => x[0]).slice(0,2).join('').toUpperCase();
  const labelStatus = status => ({ACTIVE:'Aktif',INACTIVE:'Nonaktif',UNAVAILABLE:'Tidak tersedia',OUT:'Habis',NEW:'Pesanan Baru',PROCESSING:'Diproses',READY:'Selesai',DONE:'Diambil',HELD:'Disimpan'}[status] || status);
  const badge = text => `<span class="badge ${/aktif|selesai|aman|lunas|diterima/i.test(text)?'green':/rendah|habis|nonaktif|dibatalkan/i.test(text)?'red':/proses|menunggu|disimpan/i.test(text)?'amber':'blue'}">${esc(text)}</span>`;
  const totalItems = items => (items || []).reduce((sum,item) => sum + (Number(item.price) + Number(item.addonTotal || 0)) * Number(item.qty), 0);

  function seed() {
    const outlets = [
      {id:'mataram',name:'Mataram',code:'MTR-01',address:'Jl. Pejanggik No. 18',phone:'0370 661 889',hours:'08.00–22.00',tables:8,status:'ACTIVE'},
      {id:'ampenan',name:'Ampenan',code:'AMP-02',address:'Jl. Yos Sudarso No. 7',phone:'0370 645 210',hours:'09.00–22.00',tables:10,status:'ACTIVE'},
      {id:'cakranegara',name:'Cakranegara',code:'CKR-03',address:'Jl. Selaparang No. 21',phone:'0370 632 881',hours:'08.00–21.30',tables:7,status:'ACTIVE'},
      {id:'senggigi',name:'Senggigi',code:'SNG-04',address:'Jl. Raya Senggigi No. 9',phone:'0370 693 042',hours:'10.00–23.00',tables:12,status:'ACTIVE'},
      {id:'praya',name:'Praya',code:'PRY-05',address:'Jl. Basuki Rahmat No. 11',phone:'0370 654 701',hours:'09.00–21.00',tables:6,status:'INACTIVE'}
    ];
    const categories = [
      {id:'cat-mie',name:'Mie',status:'ACTIVE'}, {id:'cat-bakso',name:'Bakso',status:'ACTIVE'},
      {id:'cat-minuman',name:'Minuman',status:'ACTIVE'}, {id:'cat-camilan',name:'Camilan',status:'ACTIVE'}
    ];
    const activeOutlets = outlets.filter(x=>x.status==='ACTIVE').map(x=>x.id);
    const rawProducts = [
      ['p1','Mie Ayam Original','MN-001','cat-mie',15000,'🍜',42],['p2','Mie Ayam Bakso','MN-002','cat-mie',20000,'🍜',28],
      ['p3','Mie Ayam Pangsit','MN-003','cat-mie',19000,'🥟',35],['p4','Mie Ayam Komplit','MN-004','cat-mie',24000,'🍜',18],
      ['p5','Bakso Biasa','MN-005','cat-bakso',16000,'🥣',31],['p6','Bakso Urat','MN-006','cat-bakso',19000,'🥣',15],
      ['p7','Bakso Komplit','MN-007','cat-bakso',23000,'🥣',20],['p8','Es Teh Manis','MN-008','cat-minuman',5000,'🥤',67],
      ['p9','Es Jeruk','MN-009','cat-minuman',8000,'🍊',26],['p10','Teh Hangat','MN-010','cat-minuman',4000,'🍵',55],
      ['p11','Air Mineral','MN-011','cat-minuman',5000,'💧',48],['p12','Pangsit Goreng','MN-012','cat-camilan',12000,'🥟',22]
    ];
    const products = rawProducts.map(([id,name,sku,categoryId,price,icon,stock]) => ({id,name,sku,categoryId,price,icon,stock,status:'ACTIVE',outletIds:[...activeOutlets]}));
    const addons = [
      {id:'a1',name:'Tambah Bakso',price:4000,status:'ACTIVE'}, {id:'a2',name:'Tambah Pangsit',price:3000,status:'ACTIVE'},
      {id:'a3',name:'Tambah Ayam',price:5000,status:'ACTIVE'}, {id:'a4',name:'Ekstra Mie',price:4000,status:'ACTIVE'},
      {id:'a5',name:'Tambah Sayur',price:2000,status:'ACTIVE'}
    ];
    const ingredients = [['mie','Mie basah','Porsi',186,80],['ayam','Ayam bumbu','Porsi',94,60],['bakso','Bakso','Pcs',42,50],['pangsit','Pangsit','Pcs',68,40],['sawi','Sawi','Ikat',18,20],['saus','Saus','Botol',12,8],['mineral','Air mineral','Botol',48,24]];
    const inventory = outlets.filter(x=>x.status==='ACTIVE').flatMap((outlet,oi)=>ingredients.map(([id,name,unit,qty,min])=>({id:`${outlet.id}-${id}`,outlet_id:outlet.id,name,unit,qty:Math.max(5,qty-oi*7),min})));
    const users = [
      {id:'u1',name:'Bima Pratama',username:'owner.demo',email:'owner@nusantara.id',phone:'08123456001',role:'Owner',outletIds:activeOutlets,status:'ACTIVE'},
      {id:'u2',name:'Siti Rahma',username:'siti',email:'siti@nusantara.id',phone:'08123456002',role:'Kasir',outletIds:['mataram'],status:'ACTIVE'},
      {id:'u3',name:'Deni Akbar',username:'deni',email:'deni@nusantara.id',phone:'08123456003',role:'Kepala Cabang',outletIds:['ampenan'],status:'ACTIVE'},
      {id:'u4',name:'Agus Dapur',username:'agus',email:'agus@nusantara.id',phone:'08123456004',role:'Dapur',outletIds:['mataram'],status:'ACTIVE'},
      {id:'u5',name:'Rina Ayu',username:'rina',email:'rina@nusantara.id',phone:'08123456005',role:'Kasir',outletIds:['cakranegara'],status:'ACTIVE'},
      {id:'u6',name:'Yusuf Maulana',username:'yusuf',email:'yusuf@nusantara.id',phone:'08123456006',role:'Kasir',outletIds:['senggigi'],status:'INACTIVE'}
    ];
    const methods = ['QRIS','Tunai','Tunai','QRIS','Transfer'];
    const transactions = Array.from({length:32},(_,i)=>{
      const outlet=outlets[i%4], product=products[i%products.length], qty=1+(i%3), date=new Date(now.getTime()-(i%24)*86400000), minutes=(19*60+42-i*7+1440)%1440;
      return {id:`TRX-2608-${String(142-i).padStart(4,'0')}`,date:date.toISOString(),time:`${String(Math.floor(minutes/60)).padStart(2,'0')}:${String(minutes%60).padStart(2,'0')}`,outlet_id:outlet.id,cashier:i%2?'Siti Rahma':'Rina Ayu',method:methods[i%methods.length],subtotal:product.price*qty,discount:i%7===0?2000:0,total:product.price*qty-(i%7===0?2000:0),status:'Selesai',items:[{name:product.name,qty,price:product.price,addons:[],addonTotal:0,note:''}]};
    });
    const orders = [
      {id:'A018',outlet_id:'mataram',table:'Meja 02',type:'DINE_IN',status:'PROCESSING',paid:false,created:now.getTime()-11*60000,items:[{name:'Mie Ayam Bakso',qty:2,price:20000,addons:['Tambah Bakso'],addonTotal:4000,note:'Tanpa sawi, kuah sedikit'},{name:'Es Teh Manis',qty:1,price:5000,addons:[],addonTotal:0,note:''}]},
      {id:'A019',outlet_id:'mataram',table:'Takeaway',type:'TAKEAWAY',status:'NEW',paid:true,method:'QRIS',created:now.getTime()-6*60000,items:[{name:'Mie Ayam Komplit',qty:1,price:24000,addons:['Tambah Pangsit'],addonTotal:3000,note:'Bakso dipisah'}]},
      {id:'A020',outlet_id:'mataram',table:'Meja 08',type:'DINE_IN',status:'READY',paid:false,created:now.getTime()-17*60000,items:[{name:'Bakso Urat',qty:2,price:19000,addons:[],addonTotal:0,note:'Tidak pedas'}]}
    ];
    return {version:VERSION,session:null,activeOutlet:'all',dashboardRange:7,productTab:'menu',orderTab:'all',shift:null,cart:[],orderType:'DINE_IN',selectedTable:'Meja 05',category:'all',outlets,categories,products,addons,priceOverrides:[],inventory,stockMovements:[],users,orders,heldOrders:[],transactions,lastReceipt:null,notifications:[{id:'n1',title:'Stok bakso menipis',text:'Cabang Mataram berada di bawah minimum stok.',read:false},{id:'n2',title:'Shift berhasil ditutup',text:'Shift Rina Ayu di Cakranegara tidak memiliki selisih kas.',read:false},{id:'n3',title:'Harga diperbarui',text:'Harga Mie Ayam Komplit Senggigi diperbarui kemarin.',read:true}]};
  }

  function load() {
    const fresh=seed();
    try {
      const old=JSON.parse(localStorage.getItem(KEY)||'null');
      if(!old) return fresh;
      if(old.version===VERSION) return {...fresh,...old,transactions:(old.transactions||fresh.transactions).map((t,i)=>({...t,time:/^\d{2}:[0-5]\d$/.test(t.time||'')?t.time:fresh.transactions[i%fresh.transactions.length].time}))};
      return {...fresh,session:old.session||null,shift:old.shift||null,cart:old.cart||[],orders:old.orders||fresh.orders,transactions:(old.transactions||fresh.transactions).map((t,i)=>({...fresh.transactions[i%fresh.transactions.length],...t,date:t.date||fresh.transactions[i%fresh.transactions.length].date,outlet_id:t.outlet_id||String(t.outlet||'Mataram').toLowerCase()})),lastReceipt:old.lastReceipt||null};
    } catch { return fresh; }
  }
  let state=load();
  const save=()=>localStorage.setItem(KEY,JSON.stringify(state));
  save();
  const outletName=id=>state.outlets.find(x=>x.id===id)?.name||id;
  const categoryName=id=>state.categories.find(x=>x.id===id)?.name||'Tanpa kategori';
  const selectedOutlet=()=>state.activeOutlet==='all'?'all':state.activeOutlet;
  const productPrice=(product,outletId)=>state.priceOverrides.find(x=>x.productId===product.id&&x.outlet_id===outletId)?.price??product.price;
  const toast=message=>{document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.innerHTML=`<strong>✓</strong>${esc(message)}`;document.body.append(el);setTimeout(()=>el.remove(),2500)};
  const stat=(label,value,detail,icon)=>`<article class="card stat-card"><div class="stat-top"><span>${esc(label)}</span><b class="stat-icon">${icon}</b></div><div class="stat-value">${esc(value)}</div><div class="trend">${esc(detail)}</div></article>`;
  const navs={owner:[['dashboard','Dashboard','⌂'],['outlets','Outlet','◫'],['reports','Penjualan','▥'],['products','Produk','◈'],['inventory','Inventori','▤'],['users','Pengguna','♙']],cashier:[['pos','Buka POS','＋'],['orders','Pesanan','▥'],['shift','Shift Kasir','◷']],kitchen:[['kitchen','Kitchen Orders','▦']]};
  const roleLabel={owner:'Owner / Super Admin',cashier:'Kasir',kitchen:'Tim Dapur'};
  const hrefFor=(role,id)=>role==='owner'?`${root}owner/${id}.html`:role==='cashier'?`${root}cashier/${id}.html`:`${root}kitchen/index.html`;

  function shell(role,title,subtitle,content,actions='') {
    const nav=navs[role].map(([id,label,icon])=>`<a href="${hrefFor(role,id)}" class="${page===id?'active':''}"><b class="nav-icon">${icon}</b><span>${label}</span></a>`).join('');
    const outletOptions=state.outlets.filter(x=>x.status==='ACTIVE').map(x=>`<option value="${x.id}" ${state.activeOutlet===x.id?'selected':''}>Cabang ${esc(x.name)}</option>`).join('');
    document.body.innerHTML=`<div class="app-shell"><aside class="sidebar"><a class="brand" href="${hrefFor(role,role==='owner'?'dashboard':role==='cashier'?'pos':'kitchen')}"><b class="brand-mark">MN</b><span>Mie Ayam<br>Nusantara</span></a><div class="nav-label">Workspace</div><nav class="nav">${nav}</nav><div class="sidebar-foot"><div class="user-chip"><div class="avatar">${initials(state.session?.name||'Demo User')}</div><div><strong>${esc(state.session?.name||'Demo User')}</strong><span>${roleLabel[role]}</span></div></div><button class="btn btn-sm btn-block" id="logoutBtn">Keluar</button></div></aside><main class="workspace"><header class="topbar"><div class="branch-picker">📍 ${role==='owner'?`<select class="icon-select" id="globalOutlet"><option value="all">Semua Cabang</option>${outletOptions}</select>`:`<span>Cabang ${esc(outletName(state.session?.outlet_id||'mataram'))}</span>`}</div><div class="top-actions"><button class="icon-btn" id="noticeBtn" aria-label="Notifikasi">♢<sup>${state.notifications.filter(x=>!x.read).length||''}</sup></button><button class="btn btn-outline btn-sm" id="resetBtn">Reset Demo</button></div></header><div class="page"><div class="page-head"><div><span class="eyebrow">${roleLabel[role]}</span><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="page-actions">${actions}</div></div>${content}</div></main></div>`;
    document.querySelector('#logoutBtn').onclick=()=>{state.session=null;save();location.href=root+'index.html'};
    document.querySelector('#resetBtn').onclick=()=>{if(confirm('Kembalikan seluruh data demo ke kondisi awal?')){state=seed();save();location.reload()}};
    document.querySelector('#noticeBtn').onclick=openNotifications;
    const picker=document.querySelector('#globalOutlet'); if(picker) picker.onchange=()=>{state.activeOutlet=picker.value;save();location.reload()};
  }

  function openNotifications(){
    document.body.insertAdjacentHTML('beforeend',`<div class="drawer-backdrop" id="drawerBack"></div><aside class="drawer"><div class="drawer-head"><div><span class="eyebrow">Aktivitas</span><h2 style="margin:.2rem 0">Notifikasi</h2></div><button class="icon-btn" id="drawerClose">×</button></div><div class="drawer-body">${state.notifications.map(n=>`<article class="notice ${n.read?'':'unread'}"><strong>${esc(n.title)}</strong><small>${esc(n.text)}</small></article>`).join('')}<button class="btn btn-outline btn-block" id="readAll">Tandai semua dibaca</button></div></aside>`);
    const close=()=>{document.querySelector('.drawer')?.remove();document.querySelector('#drawerBack')?.remove()};
    document.querySelector('#drawerBack').onclick=close;document.querySelector('#drawerClose').onclick=close;
    document.querySelector('#readAll').onclick=()=>{state.notifications.forEach(n=>n.read=true);save();close();toast('Semua notifikasi telah dibaca')};
  }
  function modal(title,body,footer=''){
    document.querySelector('#globalModal')?.remove();document.body.insertAdjacentHTML('beforeend',`<dialog id="globalModal"><div class="dialog-head"><div><span class="eyebrow">Mie Ayam Nusantara</span><h2>${esc(title)}</h2></div><button class="icon-btn" data-modal-close>×</button></div><div class="dialog-body">${body}</div>${footer?`<div class="dialog-foot">${footer}</div>`:''}</dialog>`);
    const d=document.querySelector('#globalModal');d.querySelectorAll('[data-modal-close]').forEach(b=>b.onclick=()=>d.close());d.addEventListener('close',()=>d.remove(),{once:true});d.showModal();return d;
  }
  function csvDownload(filename,rows){const csv=rows.map(row=>row.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('CSV berhasil diunduh')}
  function printReport(){document.body.classList.add('print-report');window.print();setTimeout(()=>document.body.classList.remove('print-report'),1000)}

  function renderLogin(){
    document.body.innerHTML=`<main class="login-page"><section class="login-visual"><div class="brand"><b class="brand-mark">MN</b><span>Mie Ayam Nusantara</span></div><div class="login-copy"><span class="eyebrow" style="color:#ffd0b7">Satu sistem. Semua cabang.</span><h1>Operasional rapi, rasa tetap juara.</h1><p>Pantau penjualan, layani pelanggan, dan hubungkan kasir dengan dapur melalui satu ruang kerja yang terasa sederhana.</p></div><div class="login-stats"><div class="login-stat"><strong>${state.outlets.filter(x=>x.status==='ACTIVE').length}</strong><span>Outlet aktif</span></div><div class="login-stat"><strong>99,5%</strong><span>Target uptime</span></div><div class="login-stat"><strong>&lt; 2 dtk</strong><span>Respons POS</span></div></div></section><section class="login-panel"><div class="login-box"><span class="eyebrow">Selamat datang</span><h2>Masuk ke workspace</h2><p class="muted">Gunakan akun operasional Anda.</p><form class="login-form" id="loginForm"><div class="field"><label>Username</label><input class="input" name="username" value="owner.demo" autocomplete="username" required></div><div class="field"><label>Password</label><input class="input" type="password" value="demo1234" autocomplete="current-password" required></div><div class="field"><label>Masuk sebagai</label><select class="select" name="role"><option value="owner">Owner / Super Admin</option><option value="cashier">Kasir Cabang</option><option value="kitchen">Tim Dapur</option></select></div><button class="btn btn-primary btn-block">Masuk ke Sistem →</button><div class="login-hint"><b>Mode prototipe</b><br>Pilih role untuk menjelajahi tampilan berbeda. Data hanya tersimpan di browser ini.</div></form></div></section></main>`;
    document.querySelector('#loginForm').onsubmit=e=>{e.preventDefault();const role=new FormData(e.target).get('role');state.session={role,name:role==='owner'?'Bima Pratama':role==='cashier'?'Siti Rahma':'Agus Dapur',outlet_id:'mataram'};state.activeOutlet=role==='owner'?'all':'mataram';save();location.href=role==='owner'?'owner/dashboard.html':role==='cashier'?'cashier/shift.html':'kitchen/index.html'};
  }
  const daysBetween=date=>Math.floor((now-new Date(date))/86400000);
  function filteredTransactions(range=state.dashboardRange){return state.transactions.filter(t=>(selectedOutlet()==='all'||t.outlet_id===selectedOutlet())&&daysBetween(t.date)<Number(range))}
  function renderDashboard(){
    const tx=filteredTransactions(),sales=tx.reduce((s,t)=>s+t.total,0),aov=tx.length?sales/tx.length:0;
    const daily=Array.from({length:7},(_,i)=>tx.filter(t=>daysBetween(t.date)===6-i).reduce((s,t)=>s+t.total,0)),max=Math.max(...daily,1);
    const sold={};tx.forEach(t=>(t.items||[]).forEach(i=>sold[i.name]=(sold[i.name]||0)+i.qty));const ranking=Object.entries(sold).sort((a,b)=>b[1]-a[1]).slice(0,4);
    const content=`<section class="stats-grid">${stat('Omzet periode',rp(sales),`${tx.length} transaksi`,'↗')}${stat('Total transaksi',tx.length,'berdasarkan filter','▥')}${stat('Rata-rata transaksi',rp(aov),'per transaksi','◎')}${stat('Cabang aktif',state.outlets.filter(x=>x.status==='ACTIVE').length+' outlet','operasional','◫')}</section><section class="grid-2"><article class="card section-card"><div class="section-head"><div><h2>Tren penjualan</h2><p>Omzet 7 hari terakhir pada cakupan aktif</p></div><select class="select" id="dashboardRange" style="width:auto"><option value="7" ${state.dashboardRange==7?'selected':''}>7 hari</option><option value="30" ${state.dashboardRange==30?'selected':''}>30 hari</option></select></div><div class="chart-wrap"><div class="chart">${daily.map((v,i)=>`<div class="bar-group"><div class="bar" title="${rp(v)}" style="height:${Math.max(5,v/max*92)}%"></div><span class="bar-label">${['Min','Sen','Sel','Rab','Kam','Jum','Sab'][i]}</span></div>`).join('')}</div></div></article><article class="card section-card"><div class="section-head"><div><h2>Menu terlaris</h2><p>Berdasarkan jumlah porsi</p></div><button class="btn btn-sm" id="bestSellerBtn">Lihat semua</button></div><div class="ranking">${ranking.length?ranking.map(([name,qty],i)=>`<div class="rank-row"><b class="rank-num">${i+1}</b><div><strong>${esc(name)}</strong><span>${qty} porsi</span></div><b>${Math.round(qty/Math.max(1,Object.values(sold).reduce((a,b)=>a+b,0))*100)}%</b></div>`).join(''):'<div class="empty">Belum ada penjualan pada periode ini.</div>'}</div></article></section><section class="card section-card" style="margin-top:1rem"><div class="section-head"><div><h2>Performa cabang</h2><p>Perbandingan outlet pada periode aktif</p></div><a class="btn btn-outline btn-sm" href="outlets.html">Kelola outlet</a></div>${branchTable(tx)}</section>`;
    shell('owner','Ringkasan Bisnis','Data demo operasional diperbarui secara lokal.',content,'<button class="btn btn-primary" id="dashboardPrint">Unduh laporan</button>');
    document.querySelector('#dashboardRange').onchange=e=>{state.dashboardRange=Number(e.target.value);save();renderDashboard()};
    document.querySelector('#dashboardPrint').onclick=printReport;
    document.querySelector('#bestSellerBtn').onclick=()=>modal('Ranking Menu',`<div class="ranking">${Object.entries(sold).sort((a,b)=>b[1]-a[1]).map(([name,qty],i)=>`<div class="rank-row"><b class="rank-num">${i+1}</b><div><strong>${esc(name)}</strong><span>Produk terjual</span></div><b>${qty} porsi</b></div>`).join('')||'<div class="empty">Belum ada data.</div>'}</div>`);
  }
  function branchTable(tx){return`<div class="table-wrap"><table class="table"><thead><tr><th>Cabang</th><th>Omzet</th><th>Transaksi</th><th>AOV</th><th>Status</th></tr></thead><tbody>${state.outlets.filter(x=>x.status==='ACTIVE').map(o=>{const rows=tx.filter(t=>t.outlet_id===o.id),sales=rows.reduce((s,t)=>s+t.total,0);return`<tr><td><strong>${esc(o.name)}</strong><small>${esc(o.hours)}</small></td><td>${rp(sales)}</td><td>${rows.length}</td><td>${rp(rows.length?sales/rows.length:0)}</td><td>${badge('Aktif')}</td></tr>`}).join('')}</tbody></table></div>`}

  function renderOutlets(){
    shell('owner','Daftar Outlet','Kelola identitas, jam operasional, dan status seluruh cabang.',`<div class="toolbar"><div class="search"><input class="input" id="outletSearch" placeholder="Cari nama atau kode outlet"></div><select class="select" id="outletStatus"><option value="all">Semua status</option><option value="ACTIVE">Aktif</option><option value="INACTIVE">Nonaktif</option></select></div><section class="card section-card"><div class="table-wrap"><table class="table"><thead><tr><th>Outlet</th><th>Kode</th><th>Alamat</th><th>Jam operasional</th><th>Meja</th><th>Status</th><th></th></tr></thead><tbody id="outletRows"></tbody></table></div></section>`,'<button class="btn btn-primary" id="addOutlet">＋ Tambah outlet</button>');
    const draw=()=>{const q=document.querySelector('#outletSearch').value.toLowerCase(),status=document.querySelector('#outletStatus').value;document.querySelector('#outletRows').innerHTML=state.outlets.filter(o=>(status==='all'||o.status===status)&&(o.name.toLowerCase().includes(q)||o.code.toLowerCase().includes(q))).map(o=>`<tr><td><strong>${esc(o.name)}</strong><small>Cabang ${esc(o.name)}</small></td><td>${esc(o.code)}</td><td>${esc(o.address)}</td><td>${esc(o.hours)}</td><td>${o.tables} meja</td><td>${badge(labelStatus(o.status))}</td><td><button class="btn btn-sm btn-outline" data-outlet-detail="${o.id}">Detail</button></td></tr>`).join('')||'<tr><td colspan="7"><div class="empty">Outlet tidak ditemukan.</div></td></tr>';document.querySelectorAll('[data-outlet-detail]').forEach(b=>b.onclick=()=>outletDetail(b.dataset.outletDetail))};
    document.querySelector('#outletSearch').oninput=draw;document.querySelector('#outletStatus').onchange=draw;document.querySelector('#addOutlet').onclick=()=>outletForm();draw();
  }
  function outletDetail(id){const o=state.outlets.find(x=>x.id===id),tx=state.transactions.filter(t=>t.outlet_id===id);const d=modal(`Cabang ${o.name}`,`<div class="detail-list"><div class="detail-row"><span>Kode</span><strong>${esc(o.code)}</strong></div><div class="detail-row"><span>Alamat</span><strong>${esc(o.address)}</strong></div><div class="detail-row"><span>Telepon</span><strong>${esc(o.phone)}</strong></div><div class="detail-row"><span>Jam operasional</span><strong>${esc(o.hours)}</strong></div><div class="detail-row"><span>Jumlah meja</span><strong>${o.tables} meja</strong></div><div class="detail-row"><span>Omzet demo</span><strong>${rp(tx.reduce((s,t)=>s+t.total,0))}</strong></div><div class="detail-row"><span>Status</span><strong>${badge(labelStatus(o.status))}</strong></div></div>`,`<button class="btn" data-modal-close>Tutup</button><button class="btn btn-primary" id="editOutlet">Edit outlet</button>`);d.querySelector('#editOutlet').onclick=()=>{d.close();outletForm(o)}}
  function outletForm(existing){const o=existing||{name:'',code:'',address:'',phone:'',hours:'08.00–22.00',tables:6,status:'ACTIVE'};const d=modal(existing?'Edit Outlet':'Tambah Outlet',`<form id="outletForm" class="modal-grid"><div class="field"><label>Nama cabang</label><input class="input" name="name" value="${esc(o.name)}" required></div><div class="field"><label>Kode cabang</label><input class="input" name="code" value="${esc(o.code)}" required></div><div class="field span-2"><label>Alamat</label><input class="input" name="address" value="${esc(o.address)}" required></div><div class="field"><label>Nomor telepon</label><input class="input" name="phone" value="${esc(o.phone)}"></div><div class="field"><label>Jam operasional</label><input class="input" name="hours" value="${esc(o.hours)}" required></div><div class="field"><label>Jumlah meja</label><input class="input" name="tables" type="number" min="1" value="${o.tables}" required></div><div class="field"><label>Status</label><select class="select" name="status"><option value="ACTIVE" ${o.status==='ACTIVE'?'selected':''}>Aktif</option><option value="INACTIVE" ${o.status==='INACTIVE'?'selected':''}>Nonaktif</option></select></div><div class="form-error span-2" id="outletError"></div></form>`,`<button class="btn" data-modal-close>Batal</button><button class="btn btn-primary" id="saveOutlet">Simpan</button>`);d.querySelector('#saveOutlet').onclick=()=>{const form=d.querySelector('#outletForm');if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form));if(state.outlets.some(x=>x.code.toLowerCase()===data.code.toLowerCase()&&x.id!==existing?.id)){d.querySelector('#outletError').textContent='Kode cabang sudah digunakan.';return}if(existing)Object.assign(existing,data,{tables:Number(data.tables)});else{const id=data.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')+'-'+Date.now().toString().slice(-3);state.outlets.push({...data,id,tables:Number(data.tables)});state.inventory.push(...seed().inventory.filter(x=>x.outlet_id==='mataram').map(x=>({...x,id:id+'-'+x.id.split('-').slice(1).join('-'),outlet_id:id,qty:0})));}save();d.close();toast(existing?'Outlet diperbarui':'Outlet ditambahkan');renderOutlets()}}

  function renderProducts(){
    const labels={menu:'Tambah produk',categories:'Tambah kategori',addons:'Tambah add-on',prices:'Atur harga'};
    shell('owner','Produk & Harga','Katalog terpusat dengan ketersediaan dan harga per cabang.',`<div class="tabs">${[['menu','Menu'],['categories','Kategori'],['addons','Add-on'],['prices','Harga Cabang']].map(([id,label])=>`<button class="tab ${state.productTab===id?'active':''}" data-product-tab="${id}">${label}</button>`).join('')}</div><div id="productPane"></div>`,`<button class="btn btn-primary" id="productPrimary">＋ ${labels[state.productTab]}</button>`);
    document.querySelectorAll('[data-product-tab]').forEach(b=>b.onclick=()=>{state.productTab=b.dataset.productTab;save();renderProducts()});
    document.querySelector('#productPrimary').onclick=()=>state.productTab==='menu'?productForm():state.productTab==='categories'?categoryForm():state.productTab==='addons'?addonForm():priceForm();drawProductPane();
  }
  function drawProductPane(){
    const pane=document.querySelector('#productPane');if(!pane)return;
    if(state.productTab==='menu'){
      pane.innerHTML=`<div class="toolbar"><div class="search"><input class="input" id="productSearch" placeholder="Cari produk atau SKU"></div><select class="select" id="productCategory"><option value="all">Semua kategori</option>${state.categories.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select><select class="select" id="productStatus"><option value="all">Semua status</option><option value="ACTIVE">Aktif</option><option value="UNAVAILABLE">Tidak tersedia</option><option value="OUT">Habis</option></select></div><section class="card section-card"><div class="table-wrap"><table class="table"><thead><tr><th>Produk</th><th>SKU</th><th>Kategori</th><th>Harga global</th><th>Cabang</th><th>Status</th><th></th></tr></thead><tbody id="productRows"></tbody></table></div></section>`;
      const draw=()=>{const q=pane.querySelector('#productSearch').value.toLowerCase(),cat=pane.querySelector('#productCategory').value,status=pane.querySelector('#productStatus').value;pane.querySelector('#productRows').innerHTML=state.products.filter(p=>(cat==='all'||p.categoryId===cat)&&(status==='all'||p.status===status)&&(p.name.toLowerCase().includes(q)||p.sku.toLowerCase().includes(q))).map(p=>`<tr><td><strong>${p.icon} ${esc(p.name)}</strong><small>${p.stock} stok demo</small></td><td>${esc(p.sku)}</td><td>${esc(categoryName(p.categoryId))}</td><td><strong>${rp(p.price)}</strong></td><td>${p.outletIds.length} outlet</td><td>${badge(labelStatus(p.status))}</td><td><button class="btn btn-sm" data-edit-product="${p.id}">Edit</button></td></tr>`).join('')||'<tr><td colspan="7"><div class="empty">Produk tidak ditemukan.</div></td></tr>';pane.querySelectorAll('[data-edit-product]').forEach(b=>b.onclick=()=>productForm(state.products.find(x=>x.id===b.dataset.editProduct)))};pane.querySelector('#productSearch').oninput=draw;pane.querySelector('#productCategory').onchange=draw;pane.querySelector('#productStatus').onchange=draw;draw();
    } else if(state.productTab==='categories'){
      pane.innerHTML=`<section class="card section-card"><div class="section-head"><div><h2>Kategori produk</h2><p>Kategori aktif akan tampil sebagai filter pada POS.</p></div></div><table class="table"><thead><tr><th>Kategori</th><th>Jumlah menu</th><th>Status</th><th></th></tr></thead><tbody>${state.categories.map(c=>`<tr><td><strong>${esc(c.name)}</strong><small>${esc(c.id)}</small></td><td>${state.products.filter(p=>p.categoryId===c.id).length} produk</td><td>${badge(labelStatus(c.status))}</td><td><button class="btn btn-sm" data-edit-category="${c.id}">Edit</button></td></tr>`).join('')}</tbody></table></section>`;pane.querySelectorAll('[data-edit-category]').forEach(b=>b.onclick=()=>categoryForm(state.categories.find(x=>x.id===b.dataset.editCategory)));
    } else if(state.productTab==='addons'){
      pane.innerHTML=`<section class="card section-card"><div class="section-head"><div><h2>Add-on & topping</h2><p>Add-on aktif tersedia pada modal kustomisasi POS.</p></div></div><table class="table"><thead><tr><th>Add-on</th><th>Harga</th><th>Status</th><th></th></tr></thead><tbody>${state.addons.map(a=>`<tr><td><strong>${esc(a.name)}</strong><small>${esc(a.id)}</small></td><td>${rp(a.price)}</td><td>${badge(labelStatus(a.status))}</td><td><button class="btn btn-sm" data-edit-addon="${a.id}">Edit</button></td></tr>`).join('')}</tbody></table></section>`;pane.querySelectorAll('[data-edit-addon]').forEach(b=>b.onclick=()=>addonForm(state.addons.find(x=>x.id===b.dataset.editAddon)));
    } else {
      pane.innerHTML=`<div class="toolbar"><select class="select" id="priceOutlet"><option value="all">Semua cabang</option>${state.outlets.filter(x=>x.status==='ACTIVE').map(o=>`<option value="${o.id}">${esc(o.name)}</option>`).join('')}</select></div><section class="card section-card"><table class="table"><thead><tr><th>Produk</th><th>Harga global</th><th>Cabang</th><th>Harga khusus</th><th>Harga efektif</th><th></th></tr></thead><tbody id="priceRows"></tbody></table></section>`;
      const draw=()=>{const oid=pane.querySelector('#priceOutlet').value,rows=state.outlets.filter(o=>o.status==='ACTIVE'&&(oid==='all'||o.id===oid)).flatMap(o=>state.products.slice(0,8).map(p=>{const ov=state.priceOverrides.find(x=>x.outlet_id===o.id&&x.productId===p.id);return`<tr><td><strong>${esc(p.name)}</strong></td><td>${rp(p.price)}</td><td>${esc(o.name)}</td><td>${ov?rp(ov.price):'<span class="muted">—</span>'}</td><td><strong>${rp(productPrice(p,o.id))}</strong></td><td><button class="btn btn-sm" data-price-product="${p.id}" data-price-outlet="${o.id}">${ov?'Edit':'Atur'}</button></td></tr>`}));pane.querySelector('#priceRows').innerHTML=rows.join('');pane.querySelectorAll('[data-price-product]').forEach(b=>b.onclick=()=>priceForm(b.dataset.priceProduct,b.dataset.priceOutlet))};pane.querySelector('#priceOutlet').onchange=draw;draw();
    }
  }
  function productForm(existing){const p=existing||{name:'',sku:`MN-${String(state.products.length+1).padStart(3,'0')}`,categoryId:state.categories[0]?.id||'',price:'',icon:'🍜',stock:0,status:'ACTIVE',outletIds:state.outlets.filter(x=>x.status==='ACTIVE').map(x=>x.id)};const d=modal(existing?'Edit Menu':'Tambah Menu',`<form id="masterForm" class="modal-grid"><div class="field"><label>Nama produk</label><input class="input" name="name" value="${esc(p.name)}" required></div><div class="field"><label>SKU</label><input class="input" name="sku" value="${esc(p.sku)}" required></div><div class="field"><label>Kategori</label><select class="select" name="categoryId">${state.categories.filter(c=>c.status==='ACTIVE'||c.id===p.categoryId).map(c=>`<option value="${c.id}" ${c.id===p.categoryId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Ikon menu</label><select class="select" name="icon">${['🍜','🥣','🥟','🥤','🍊','🍵','💧','🍚'].map(i=>`<option ${i===p.icon?'selected':''}>${i}</option>`).join('')}</select></div><div class="field"><label>Harga global</label><input class="input" name="price" type="number" min="0" value="${p.price}" required></div><div class="field"><label>Stok tampilan</label><input class="input" name="stock" type="number" min="0" value="${p.stock}" required></div><div class="field"><label>Status</label><select class="select" name="status"><option value="ACTIVE" ${p.status==='ACTIVE'?'selected':''}>Aktif</option><option value="UNAVAILABLE" ${p.status==='UNAVAILABLE'?'selected':''}>Tidak tersedia</option><option value="OUT" ${p.status==='OUT'?'selected':''}>Habis</option></select></div><div class="field span-2"><label>Tersedia di cabang</label><div class="check-grid">${state.outlets.filter(x=>x.status==='ACTIVE').map(o=>`<label class="check-card"><input type="checkbox" name="outletIds" value="${o.id}" ${p.outletIds.includes(o.id)?'checked':''}><span><strong>${esc(o.name)}</strong><small>${esc(o.code)}</small></span></label>`).join('')}</div></div><div class="form-error span-2" id="masterError"></div></form>`,`<button class="btn" data-modal-close>Batal</button><button class="btn btn-primary" id="saveMaster">Simpan</button>`);d.querySelector('#saveMaster').onclick=()=>{const form=d.querySelector('#masterForm');if(!form.reportValidity())return;const fd=new FormData(form),data=Object.fromEntries(fd);data.outletIds=fd.getAll('outletIds');if(!data.outletIds.length){d.querySelector('#masterError').textContent='Pilih minimal satu cabang.';return}if(state.products.some(x=>x.sku.toLowerCase()===data.sku.toLowerCase()&&x.id!==existing?.id)){d.querySelector('#masterError').textContent='SKU sudah digunakan.';return}Object.assign(data,{price:Number(data.price),stock:Number(data.stock)});if(existing)Object.assign(existing,data);else state.products.push({...data,id:uid('p')});save();d.close();toast(existing?'Produk diperbarui':'Produk ditambahkan');renderProducts()}}
  function categoryForm(existing){const c=existing||{name:'',status:'ACTIVE'};const d=modal(existing?'Edit Kategori':'Tambah Kategori',`<form id="simpleForm"><div class="field"><label>Nama kategori</label><input class="input" name="name" value="${esc(c.name)}" required></div><div class="field" style="margin-top:1rem"><label>Status</label><select class="select" name="status"><option value="ACTIVE" ${c.status==='ACTIVE'?'selected':''}>Aktif</option><option value="INACTIVE" ${c.status==='INACTIVE'?'selected':''}>Nonaktif</option></select></div><div class="form-error" id="simpleError"></div></form>`,`<button class="btn" data-modal-close>Batal</button><button class="btn btn-primary" id="saveSimple">Simpan</button>`);d.querySelector('#saveSimple').onclick=()=>{const form=d.querySelector('#simpleForm');if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form));if(state.categories.some(x=>x.name.toLowerCase()===data.name.toLowerCase()&&x.id!==existing?.id)){d.querySelector('#simpleError').textContent='Nama kategori sudah ada.';return}if(existing)Object.assign(existing,data);else state.categories.push({...data,id:uid('cat')});save();d.close();toast('Kategori disimpan');renderProducts()}}
  function addonForm(existing){const a=existing||{name:'',price:'',status:'ACTIVE'};const d=modal(existing?'Edit Add-on':'Tambah Add-on',`<form id="simpleForm" class="modal-grid"><div class="field"><label>Nama add-on</label><input class="input" name="name" value="${esc(a.name)}" required></div><div class="field"><label>Harga</label><input class="input" type="number" name="price" min="0" value="${a.price}" required></div><div class="field"><label>Status</label><select class="select" name="status"><option value="ACTIVE" ${a.status==='ACTIVE'?'selected':''}>Aktif</option><option value="INACTIVE" ${a.status==='INACTIVE'?'selected':''}>Nonaktif</option></select></div></form>`,`<button class="btn" data-modal-close>Batal</button><button class="btn btn-primary" id="saveSimple">Simpan</button>`);d.querySelector('#saveSimple').onclick=()=>{const form=d.querySelector('#simpleForm');if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form));data.price=Number(data.price);if(existing)Object.assign(existing,data);else state.addons.push({...data,id:uid('a')});save();d.close();toast('Add-on disimpan');renderProducts()}}
  function priceForm(productId,outletId){const d=modal('Harga Khusus Cabang',`<form id="priceForm" class="modal-grid"><div class="field"><label>Produk</label><select class="select" name="productId">${state.products.map(p=>`<option value="${p.id}" ${p.id===productId?'selected':''}>${esc(p.name)} · ${rp(p.price)}</option>`).join('')}</select></div><div class="field"><label>Cabang</label><select class="select" name="outlet_id">${state.outlets.filter(x=>x.status==='ACTIVE').map(o=>`<option value="${o.id}" ${o.id===outletId?'selected':''}>${esc(o.name)}</option>`).join('')}</select></div><div class="field span-2"><label>Harga khusus</label><input class="input" name="price" type="number" min="0" value="${state.priceOverrides.find(x=>x.productId===productId&&x.outlet_id===outletId)?.price||''}" placeholder="Kosongkan untuk memakai harga global"></div></form>`,`<button class="btn btn-danger" id="resetPrice">Hapus override</button><button class="btn" data-modal-close>Batal</button><button class="btn btn-primary" id="savePrice">Simpan</button>`);const read=()=>Object.fromEntries(new FormData(d.querySelector('#priceForm')));d.querySelector('#savePrice').onclick=()=>{const data=read(),idx=state.priceOverrides.findIndex(x=>x.productId===data.productId&&x.outlet_id===data.outlet_id);if(data.price===''){if(idx>=0)state.priceOverrides.splice(idx,1)}else if(idx>=0)state.priceOverrides[idx].price=Number(data.price);else state.priceOverrides.push({...data,price:Number(data.price)});save();d.close();toast('Harga cabang diperbarui');renderProducts()};d.querySelector('#resetPrice').onclick=()=>{const data=read();state.priceOverrides=state.priceOverrides.filter(x=>!(x.productId===data.productId&&x.outlet_id===data.outlet_id));save();d.close();toast('Kembali ke harga global');renderProducts()}}

  function renderInventory(){
    const initial=selectedOutlet()==='all'?'mataram':selectedOutlet();
    shell('owner','Stok Cabang','Pantau saldo bahan dan lakukan penyesuaian stok cabang.',`<div class="toolbar"><select class="select" id="inventoryOutlet">${state.outlets.filter(x=>x.status==='ACTIVE').map(o=>`<option value="${o.id}" ${o.id===initial?'selected':''}>Cabang ${esc(o.name)}</option>`).join('')}</select><div class="search"><input class="input" id="inventorySearch" placeholder="Cari bahan"></div><select class="select" id="inventoryStatus"><option value="all">Semua status</option><option value="low">Stok rendah</option></select></div><div id="inventoryContent"></div>`,'<button class="btn btn-primary" id="stockInBtn">＋ Stok masuk</button>');
    const draw=()=>{const oid=document.querySelector('#inventoryOutlet').value,q=document.querySelector('#inventorySearch').value.toLowerCase(),status=document.querySelector('#inventoryStatus').value,all=state.inventory.filter(x=>x.outlet_id===oid),rows=all.filter(x=>x.name.toLowerCase().includes(q)&&(status==='all'||x.qty<x.min));document.querySelector('#inventoryContent').innerHTML=`<section class="stats-grid">${stat('Total item',all.length+' bahan','cabang terpilih','▤')}${stat('Stok rendah',all.filter(x=>x.qty<x.min).length+' item','perlu tindakan','!')}${stat('Stok masuk',state.stockMovements.filter(x=>x.outlet_id===oid&&x.type==='Stock In').reduce((s,x)=>s+x.qty,0)+' unit','histori demo','↓')}${stat('Adjustment',state.stockMovements.filter(x=>x.outlet_id===oid&&x.type==='Adjustment').length+' kali','histori demo','↕')}</section><section class="card section-card"><div class="section-head"><div><h2>Posisi stok</h2><p>${esc(outletName(oid))} · data lokal</p></div><button class="btn btn-outline btn-sm" id="movementBtn">Riwayat movement</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Bahan</th><th>Satuan</th><th>Stok</th><th>Minimum</th><th>Level</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(i=>`<tr><td><strong>${esc(i.name)}</strong><small>${esc(i.id)}</small></td><td>${esc(i.unit)}</td><td><strong>${i.qty}</strong></td><td>${i.min}</td><td style="min-width:130px"><div class="progress ${i.qty<i.min?'low':''}"><span style="width:${Math.min(100,i.qty/Math.max(1,i.min)*55)}%"></span></div></td><td>${badge(i.qty<i.min?'Stok rendah':'Aman')}</td><td><button class="btn btn-sm" data-adjust="${i.id}">Sesuaikan</button></td></tr>`).join('')||'<tr><td colspan="7"><div class="empty">Bahan tidak ditemukan.</div></td></tr>'}</tbody></table></div></section>`;document.querySelector('#movementBtn').onclick=()=>movementHistory(oid);document.querySelectorAll('[data-adjust]').forEach(b=>b.onclick=()=>stockForm('Adjustment',state.inventory.find(x=>x.id===b.dataset.adjust)));};
    document.querySelector('#inventoryOutlet').onchange=draw;document.querySelector('#inventorySearch').oninput=draw;document.querySelector('#inventoryStatus').onchange=draw;document.querySelector('#stockInBtn').onclick=()=>stockForm('Stock In',null,document.querySelector('#inventoryOutlet').value);draw();
  }
  function stockForm(type,item,outletId){const oid=item?.outlet_id||outletId;const d=modal(type==='Stock In'?'Stok Masuk':'Penyesuaian Stok',`<form id="stockForm" class="modal-grid"><div class="field"><label>Cabang</label><input class="input" value="${esc(outletName(oid))}" disabled></div><div class="field"><label>Bahan</label>${item?`<input class="input" value="${esc(item.name)}" disabled>`:`<select class="select" name="itemId">${state.inventory.filter(x=>x.outlet_id===oid).map(i=>`<option value="${i.id}">${esc(i.name)} · ${i.qty} ${esc(i.unit)}</option>`).join('')}</select>`}</div><div class="field"><label>${type==='Stock In'?'Jumlah masuk':'Stok aktual'}</label><input class="input" name="qty" type="number" min="0" required></div><div class="field"><label>Alasan / referensi</label><input class="input" name="reason" placeholder="Contoh: pembelian harian" required></div></form>`,`<button class="btn" data-modal-close>Batal</button><button class="btn btn-primary" id="saveStock">Simpan</button>`);d.querySelector('#saveStock').onclick=()=>{const form=d.querySelector('#stockForm');if(!form.reportValidity())return;const fd=Object.fromEntries(new FormData(form)),target=item||state.inventory.find(x=>x.id===fd.itemId),value=Number(fd.qty),delta=type==='Stock In'?value:value-target.qty;if(type==='Stock In')target.qty+=value;else target.qty=value;state.stockMovements.unshift({id:uid('mov'),outlet_id:oid,itemId:target.id,itemName:target.name,type,qty:Math.abs(delta),delta,reason:fd.reason,user:state.session?.name||'Bima Pratama',date:new Date().toISOString()});save();d.close();toast('Stok berhasil diperbarui');renderInventory()}}
  function movementHistory(oid){modal('Riwayat Stock Movement',`<div class="table-wrap"><table class="table"><thead><tr><th>Waktu</th><th>Bahan</th><th>Jenis</th><th>Perubahan</th><th>Alasan</th></tr></thead><tbody>${state.stockMovements.filter(x=>x.outlet_id===oid).map(m=>`<tr><td>${new Date(m.date).toLocaleString('id-ID')}</td><td><strong>${esc(m.itemName)}</strong><small>${esc(m.user)}</small></td><td>${badge(m.type)}</td><td><strong>${m.delta>0?'+':''}${m.delta}</strong></td><td>${esc(m.reason)}</td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">Belum ada movement.</div></td></tr>'}</tbody></table></div>`,`<button class="btn" data-modal-close>Tutup</button>`)}

  function renderUsers(){
    shell('owner','Pengguna & Akses','Kelola role, outlet penugasan, dan status akun.',`<div class="toolbar"><div class="search"><input class="input" id="userSearch" placeholder="Cari nama, email, atau role"></div><select class="select" id="userRole"><option value="all">Semua role</option>${['Owner','Manager Area','Kepala Cabang','Kasir','Dapur'].map(r=>`<option>${r}</option>`).join('')}</select></div><section class="card section-card"><table class="table"><thead><tr><th>Pengguna</th><th>Role</th><th>Cabang</th><th>Username</th><th>Status</th><th></th></tr></thead><tbody id="userRows"></tbody></table></section>`,'<button class="btn btn-primary" id="addUser">＋ Tambah pengguna</button>');
    const draw=()=>{const q=document.querySelector('#userSearch').value.toLowerCase(),role=document.querySelector('#userRole').value;document.querySelector('#userRows').innerHTML=state.users.filter(u=>(role==='all'||u.role===role)&&`${u.name} ${u.email} ${u.role}`.toLowerCase().includes(q)).map(u=>`<tr><td><div style="display:flex;gap:.65rem;align-items:center"><div class="avatar">${initials(u.name)}</div><div><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></div></div></td><td>${esc(u.role)}</td><td>${u.outletIds.length===state.outlets.filter(x=>x.status==='ACTIVE').length?'Semua cabang':u.outletIds.map(outletName).join(', ')}</td><td>${esc(u.username)}</td><td>${badge(labelStatus(u.status))}</td><td><button class="btn btn-sm" data-edit-user="${u.id}">Edit akses</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">Pengguna tidak ditemukan.</div></td></tr>';document.querySelectorAll('[data-edit-user]').forEach(b=>b.onclick=()=>userForm(state.users.find(x=>x.id===b.dataset.editUser)))};document.querySelector('#userSearch').oninput=draw;document.querySelector('#userRole').onchange=draw;document.querySelector('#addUser').onclick=()=>userForm();draw();
  }
  function userForm(existing){const u=existing||{name:'',username:'',email:'',phone:'',role:'Kasir',outletIds:['mataram'],status:'ACTIVE'};const d=modal(existing?'Edit Pengguna':'Tambah Pengguna',`<form id="userForm" class="modal-grid"><div class="field"><label>Nama</label><input class="input" name="name" value="${esc(u.name)}" required></div><div class="field"><label>Username</label><input class="input" name="username" value="${esc(u.username)}" required></div><div class="field"><label>Email</label><input class="input" name="email" type="email" value="${esc(u.email)}" required></div><div class="field"><label>Nomor HP</label><input class="input" name="phone" value="${esc(u.phone)}"></div><div class="field"><label>Role</label><select class="select" name="role">${['Owner','Manager Area','Kepala Cabang','Kasir','Dapur'].map(r=>`<option ${r===u.role?'selected':''}>${r}</option>`).join('')}</select></div><div class="field"><label>Status</label><select class="select" name="status"><option value="ACTIVE" ${u.status==='ACTIVE'?'selected':''}>Aktif</option><option value="INACTIVE" ${u.status==='INACTIVE'?'selected':''}>Nonaktif</option></select></div><div class="field span-2"><label>Akses cabang</label><div class="check-grid">${state.outlets.filter(x=>x.status==='ACTIVE').map(o=>`<label class="check-card"><input type="checkbox" name="outletIds" value="${o.id}" ${u.outletIds.includes(o.id)?'checked':''}><span><strong>${esc(o.name)}</strong><small>${esc(o.code)}</small></span></label>`).join('')}</div></div><div class="form-error span-2" id="userError"></div></form>`,`<button class="btn" data-modal-close>Batal</button><button class="btn btn-primary" id="saveUser">Simpan</button>`);d.querySelector('#saveUser').onclick=()=>{const form=d.querySelector('#userForm');if(!form.reportValidity())return;const fd=new FormData(form),data=Object.fromEntries(fd);data.outletIds=fd.getAll('outletIds');if(!data.outletIds.length){d.querySelector('#userError').textContent='Pilih minimal satu cabang.';return}if(state.users.some(x=>x.username.toLowerCase()===data.username.toLowerCase()&&x.id!==existing?.id)){d.querySelector('#userError').textContent='Username sudah digunakan.';return}if(existing)Object.assign(existing,data);else state.users.push({...data,id:uid('u')});save();d.close();toast('Pengguna disimpan');renderUsers()}}

  function renderReports(){
    shell('owner','Penjualan & Laporan','Analisis transaksi lintas outlet dan metode pembayaran.',`<div class="toolbar"><select class="select" id="reportRange"><option value="7">7 hari terakhir</option><option value="30">30 hari terakhir</option><option value="1">Hari ini</option></select><select class="select" id="reportOutlet"><option value="all">Semua cabang</option>${state.outlets.filter(x=>x.status==='ACTIVE').map(o=>`<option value="${o.id}">${esc(o.name)}</option>`).join('')}</select><select class="select" id="reportMethod"><option value="all">Semua metode</option><option>Tunai</option><option>QRIS</option><option>Transfer</option></select><button class="btn btn-dark" id="applyReport">Terapkan filter</button></div><div id="reportContent"></div>`,'<button class="btn btn-outline" id="csvReport">Ekspor Excel</button><button class="btn btn-primary" id="pdfReport">Ekspor PDF</button>');
    let visible=[];const draw=()=>{const range=Number(document.querySelector('#reportRange').value),oid=document.querySelector('#reportOutlet').value,method=document.querySelector('#reportMethod').value;visible=state.transactions.filter(t=>daysBetween(t.date)<range&&(oid==='all'||t.outlet_id===oid)&&(method==='all'||t.method===method));const gross=visible.reduce((s,t)=>s+t.subtotal,0),discount=visible.reduce((s,t)=>s+(t.discount||0),0),net=visible.reduce((s,t)=>s+t.total,0);const methods={};visible.forEach(t=>{methods[t.method]??={count:0,total:0};methods[t.method].count++;methods[t.method].total+=t.total});document.querySelector('#reportContent').innerHTML=`<section class="stats-grid">${stat('Gross sales',rp(gross),`${visible.length} transaksi`,'↗')}${stat('Diskon',rp(discount),'periode aktif','%')}${stat('Net sales',rp(net),'setelah diskon','◎')}${stat('AOV',rp(visible.length?net/visible.length:0),'per transaksi','▥')}</section><section class="grid-2"><article class="card section-card"><div class="section-head"><div><h2>Transaksi</h2><p>${visible.length} hasil filter</p></div></div>${transactionTable(visible,true)}</article><article class="card section-card"><div class="section-head"><div><h2>Metode pembayaran</h2><p>Distribusi net sales</p></div></div><div class="ranking">${Object.entries(methods).map(([name,v],i)=>`<div class="rank-row"><b class="rank-num">${i+1}</b><div><strong>${esc(name)}</strong><span>${v.count} transaksi</span></div><b>${rp(v.total)}</b></div>`).join('')||'<div class="empty">Tidak ada data.</div>'}</div></article></section>`;document.querySelectorAll('[data-transaction]').forEach(b=>b.onclick=()=>transactionDetail(b.dataset.transaction))};document.querySelector('#applyReport').onclick=()=>{draw();toast('Filter laporan diterapkan')};document.querySelector('#csvReport').onclick=()=>csvDownload('laporan-penjualan.csv',[['ID','Tanggal','Cabang','Kasir','Metode','Subtotal','Diskon','Total'],...visible.map(t=>[t.id,t.date.slice(0,10),outletName(t.outlet_id),t.cashier,t.method,t.subtotal,t.discount,t.total])]);document.querySelector('#pdfReport').onclick=printReport;draw();
  }
  function transactionTable(rows,actions=false){return`<div class="table-wrap"><table class="table"><thead><tr><th>ID / Waktu</th><th>Cabang</th><th>Metode</th><th>Total</th><th>Status</th>${actions?'<th></th>':''}</tr></thead><tbody>${rows.map(t=>`<tr><td><strong>${esc(t.id)}</strong><small>${esc(t.time)} WITA · ${esc(t.cashier)}</small></td><td>${esc(outletName(t.outlet_id))}</td><td>${esc(t.method)}</td><td><strong>${rp(t.total)}</strong></td><td>${badge(t.status)}</td>${actions?`<td><button class="btn btn-sm" data-transaction="${t.id}">Detail</button></td>`:''}</tr>`).join('')||`<tr><td colspan="${actions?6:5}"><div class="empty">Tidak ada transaksi.</div></td></tr>`}</tbody></table></div>`}
  function transactionDetail(id){const t=state.transactions.find(x=>x.id===id);modal(`Transaksi ${t.id}`,`<div class="detail-list"><div class="detail-row"><span>Cabang</span><strong>${esc(outletName(t.outlet_id))}</strong></div><div class="detail-row"><span>Kasir</span><strong>${esc(t.cashier)}</strong></div><div class="detail-row"><span>Metode</span><strong>${esc(t.method)}</strong></div>${(t.items||[]).map(i=>`<div class="detail-row"><span>${i.qty}× ${esc(i.name)}</span><strong>${rp((i.price+(i.addonTotal||0))*i.qty)}</strong></div>`).join('')}<div class="detail-row"><span>Diskon</span><strong>${rp(t.discount||0)}</strong></div><div class="detail-row"><span>Total</span><strong>${rp(t.total)}</strong></div></div>`,`<button class="btn" data-modal-close>Tutup</button>`)}

  function renderShift(){
    if(!state.shift){shell('cashier','Mulai Shift','Buka shift sebelum menerima transaksi pertama.',`<section class="card section-card" style="max-width:650px;margin:auto"><div style="text-align:center;padding:1rem"><div class="brand-mark" style="margin:auto">◷</div><h2>Siapkan kas untuk hari ini</h2><p class="muted">Kas awal digunakan untuk menghitung expected cash saat shift ditutup.</p></div><form id="openShift" style="display:grid;gap:1rem;max-width:420px;margin:1rem auto 2rem"><div class="field"><label>Kasir</label><input class="input" value="Siti Rahma" disabled></div><div class="field"><label>Outlet</label><input class="input" value="Mie Ayam Nusantara — Mataram" disabled></div><div class="field"><label>Kas awal</label><input class="input" type="number" name="opening" value="300000" min="0" required></div><button class="btn btn-primary btn-block">Buka Shift & Masuk POS →</button></form></section>`);document.querySelector('#openShift').onsubmit=e=>{e.preventDefault();state.shift={openedAt:new Date().toISOString(),opening:Number(new FormData(e.target).get('opening')),transactionStart:state.transactions.length};save();toast('Shift berhasil dibuka');setTimeout(()=>location.href='pos.html',400)};return}
    const shiftTx=state.transactions.slice(0,Math.max(0,state.transactions.length-(state.shift.transactionStart||state.transactions.length))),cash=shiftTx.filter(t=>t.method==='Tunai').reduce((s,t)=>s+t.total,0),nonCash=shiftTx.filter(t=>t.method!=='Tunai').reduce((s,t)=>s+t.total,0),expected=state.shift.opening+cash;
    shell('cashier','Shift Kasir','Shift aktif sejak '+new Date(state.shift.openedAt).toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'}),`<section class="stats-grid">${stat('Kas awal',rp(state.shift.opening),'tercatat','◷')}${stat('Penjualan tunai',rp(cash),'shift ini','▥')}${stat('QRIS & transfer',rp(nonCash),'shift ini','◇')}${stat('Expected cash',rp(expected),'di laci','◎')}</section><section class="grid-2"><article class="card section-card"><div class="section-head"><div><h2>Transaksi shift</h2><p>${shiftTx.length} transaksi sejak shift dibuka</p></div>${badge('Aktif')}</div>${transactionTable(shiftTx.slice(0,8))}</article><article class="card section-card"><h2 style="font-size:1rem">Tutup shift</h2><p class="muted tiny">Hitung seluruh uang fisik di laci sebelum menutup shift.</p><form id="closeShift" style="display:grid;gap:.8rem;margin-top:1rem"><div class="field"><label>Actual cash</label><input class="input" name="actual" type="number" value="${expected}"></div><div class="login-hint" id="cashDifference">Expected cash: <b>${rp(expected)}</b><br>Selisih: <b>Rp0</b></div><button class="btn btn-danger btn-block">Tutup Shift</button></form></article></section>`,'<a class="btn btn-primary" href="pos.html">Buka POS →</a>');const actual=document.querySelector('[name=actual]');actual.oninput=()=>document.querySelector('#cashDifference').innerHTML=`Expected cash: <b>${rp(expected)}</b><br>Selisih: <b>${rp(Number(actual.value)-expected)}</b>`;document.querySelector('#closeShift').onsubmit=e=>{e.preventDefault();if(confirm('Tutup shift sekarang?')){state.notifications.unshift({id:uid('n'),title:'Shift ditutup',text:`Siti Rahma menutup shift dengan selisih ${rp(Number(actual.value)-expected)}.`,read:false});state.shift=null;state.cart=[];save();toast('Shift telah ditutup');setTimeout(()=>location.reload(),400)}};
  }
  function posHeader(){return`<header class="pos-top"><a class="brand" href="shift.html"><b class="brand-mark">MN</b><span>POS Mataram</span></a><div class="search"><input class="input" id="posSearch" placeholder="Cari menu atau kode produk…"></div><div class="pos-context"><a class="btn btn-outline btn-sm" href="orders.html">Pesanan <b>${state.orders.filter(o=>o.status!=='DONE').length+state.heldOrders.length}</b></a><a class="btn btn-sm" href="shift.html">Siti · Shift</a></div></header>`}
  function renderPos(){
    if(!state.shift){document.body.innerHTML=`<main class="login-panel" style="min-height:100vh"><div class="login-box" style="text-align:center"><div class="brand-mark" style="margin:auto">!</div><h2>Shift belum dibuka</h2><p class="muted">Buka shift terlebih dahulu sebelum membuat transaksi.</p><a class="btn btn-primary btn-block" href="shift.html">Buka Shift</a></div></main>`;return}
    const cats=state.categories.filter(c=>c.status==='ACTIVE');
    document.body.innerHTML=`<main class="pos-shell"><section class="pos-main">${posHeader()}<div class="pos-content"><div class="category-strip">${[['all','Semua'],...cats.map(c=>[c.id,c.name])].map(([id,name])=>`<button class="category ${state.category===id?'active':''}" data-cat="${id}">${esc(name)}</button>`).join('')}</div><div class="product-grid" id="productGrid"></div></div></section><aside class="cart"><div class="cart-head"><div class="cart-head-top"><div><span class="eyebrow">Pesanan baru</span><strong style="display:block">#${nextOrderId()}</strong></div><button class="icon-btn" id="clearCart" aria-label="Kosongkan cart">×</button></div><div class="order-type"><button data-type="DINE_IN" class="${state.orderType==='DINE_IN'?'active':''}">Dine In</button><button data-type="TAKEAWAY" class="${state.orderType==='TAKEAWAY'?'active':''}">Takeaway</button></div><button class="table-choice ${state.orderType==='TAKEAWAY'?'hidden':''}" id="tableChoice"><span>Meja pelanggan</span><strong>${esc(state.selectedTable||'Pilih meja')} ›</strong></button></div><div class="cart-items" id="cartItems"></div><div class="cart-foot" id="cartFoot"></div></aside></main>${productDialog()}${paymentDialog()}${tableDialog()}`;
    const drawProducts=()=>{const q=document.querySelector('#posSearch').value.toLowerCase(),available=state.products.filter(p=>p.status==='ACTIVE'&&p.outletIds.includes('mataram')&&(state.category==='all'||p.categoryId===state.category)&&(p.name.toLowerCase().includes(q)||p.sku.toLowerCase().includes(q)));document.querySelector('#productGrid').innerHTML=available.map(p=>`<button class="product" data-product="${p.id}"><div class="product-art"><span class="bowl">${p.icon}</span></div><div class="product-info"><span class="product-meta">${p.stock} stok</span><div class="product-name">${esc(p.name)}</div><div class="product-price">${rp(productPrice(p,'mataram'))}</div></div></button>`).join('')||'<div class="empty">Tidak ada menu tersedia.</div>';document.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>openProduct(b.dataset.product))};
    document.querySelector('#posSearch').oninput=drawProducts;document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{state.category=b.dataset.cat;save();renderPos()});document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{state.orderType=b.dataset.type;save();renderPos()});document.querySelector('#tableChoice').onclick=()=>document.querySelector('#tableDialog').showModal();document.querySelector('#clearCart').onclick=()=>{if(!state.cart.length||confirm('Kosongkan seluruh cart?')){state.cart=[];save();drawCart()}};drawProducts();drawCart();bindPosDialogs();
  }
  function nextOrderId(){const nums=[...state.orders,...state.heldOrders].map(o=>Number(String(o.id).replace(/\D/g,''))).filter(Number.isFinite);return 'A'+String(Math.max(20,...nums)+1).padStart(3,'0')}
  function productDialog(){return`<dialog id="productDialog"><form id="productForm"><div class="dialog-head"><div><span class="eyebrow">Kustomisasi menu</span><h2 id="dialogProductName">Produk</h2></div><button type="button" class="icon-btn" data-close>×</button></div><div class="dialog-body"><input type="hidden" name="id"><div class="field"><label>Varian</label><select class="select" name="variant"><option value="Regular">Regular</option><option value="Porsi besar">Porsi besar (+Rp4.000)</option></select></div><div class="field" style="margin-top:1rem"><label>Add-on / topping</label><div class="option-grid">${state.addons.filter(a=>a.status==='ACTIVE').map(a=>`<label class="option-card"><input type="checkbox" name="addon" value="${a.id}"> ${esc(a.name)}<small style="display:block;margin-left:22px;color:var(--red)">+${rp(a.price)}</small></label>`).join('')}</div></div><div class="field" style="margin-top:1rem"><label>Catatan dapur</label><textarea class="textarea" name="note" rows="3" placeholder="Contoh: tanpa sawi, kuah sedikit"></textarea></div></div><div class="dialog-foot"><button type="button" class="btn" data-close>Batal</button><button class="btn btn-primary">Tambah ke Pesanan</button></div></form></dialog>`}
  function paymentDialog(){return`<dialog id="paymentDialog"><form id="paymentForm"><div class="dialog-head"><div><span class="eyebrow">Pembayaran</span><h2>Selesaikan transaksi</h2></div><button type="button" class="icon-btn" data-close>×</button></div><div class="dialog-body"><div class="summary-line total"><span>Total tagihan</span><strong id="payTotal"></strong></div><div class="field" style="margin-top:1rem"><label>Metode pembayaran</label><select class="select" name="method" id="payMethod"><option>Tunai</option><option>QRIS</option><option>Transfer</option></select></div><div class="field" id="cashField" style="margin-top:1rem"><label>Jumlah dibayar</label><input class="input" type="number" name="paid" id="paidAmount"></div><div class="login-hint" id="changeInfo" style="margin-top:1rem">Kembalian: <b>Rp0</b></div></div><div class="dialog-foot"><button type="button" class="btn" data-close>Batal</button><button class="btn btn-primary">Konfirmasi Pembayaran</button></div></form></dialog>`}
  function tableDialog(){const occupied=state.orders.filter(o=>o.outlet_id==='mataram'&&o.type==='DINE_IN'&&o.status!=='DONE').map(o=>o.table);const tables=state.outlets.find(x=>x.id==='mataram')?.tables||8;return`<dialog id="tableDialog"><div class="dialog-head"><h2>Pilih meja tersedia</h2><button class="icon-btn" data-close>×</button></div><div class="dialog-body"><div class="option-grid">${Array.from({length:tables},(_,i)=>{const name=`Meja ${String(i+1).padStart(2,'0')}`,busy=occupied.includes(name);return`<button class="option-card btn" ${busy?'disabled':''} data-table="${name}">${name}<small>${busy?'Terisi':'Kosong'}</small></button>`}).join('')}</div></div></dialog>`}
  function openProduct(id){const p=state.products.find(x=>x.id===id),d=document.querySelector('#productDialog');d.querySelector('[name=id]').value=id;d.querySelector('#dialogProductName').textContent=p.name;d.querySelectorAll('input[type=checkbox]').forEach(x=>x.checked=false);d.querySelector('[name=note]').value='';d.showModal()}
  function drawCart(){const box=document.querySelector('#cartItems'),foot=document.querySelector('#cartFoot');if(!box)return;if(!state.cart.length){box.innerHTML='<div class="empty"><div style="font-size:2rem">🍜</div><strong>Keranjang masih kosong</strong><p class="tiny">Pilih menu untuk mulai pesanan.</p></div>';foot.innerHTML='<button class="btn btn-primary btn-block" disabled>Belum ada pesanan</button>';return}box.innerHTML=state.cart.map((i,n)=>`<div class="cart-item"><div><h4>${esc(i.name)}</h4><p>${esc(i.variant)}${i.addons.length?' · '+i.addons.map(esc).join(', '):''}</p>${i.note?`<p>📝 ${esc(i.note)}</p>`:''}<div class="qty"><button data-minus="${n}">−</button><span>${i.qty}</span><button data-plus="${n}">＋</button></div></div><div class="cart-price">${rp((i.price+i.addonTotal)*i.qty)}<button data-remove="${n}">Hapus</button></div></div>`).join('');const subtotal=totalItems(state.cart);foot.innerHTML=`<div class="summary-line"><span>Subtotal</span><b>${rp(subtotal)}</b></div><div class="summary-line"><span>Diskon</span><b>Rp0</b></div><div class="summary-line total"><span>Total</span><strong>${rp(subtotal)}</strong></div><div class="cart-actions"><button class="btn btn-outline" id="holdBtn">Simpan</button><button class="btn btn-primary" id="checkoutBtn">${state.orderType==='DINE_IN'?'Kirim ke Dapur':'Bayar & Kirim'} →</button></div>`;box.querySelectorAll('[data-plus]').forEach(b=>b.onclick=()=>{state.cart[b.dataset.plus].qty++;save();drawCart()});box.querySelectorAll('[data-minus]').forEach(b=>b.onclick=()=>{state.cart[b.dataset.minus].qty=Math.max(1,state.cart[b.dataset.minus].qty-1);save();drawCart()});box.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{state.cart.splice(Number(b.dataset.remove),1);save();drawCart()});document.querySelector('#holdBtn').onclick=holdCart;document.querySelector('#checkoutBtn').onclick=()=>state.orderType==='DINE_IN'?createOrder(false):openPayment()}
  function holdCart(){if(!state.cart.length)return;state.heldOrders.unshift({id:nextOrderId(),outlet_id:'mataram',table:state.orderType==='DINE_IN'?state.selectedTable:'Takeaway',type:state.orderType,status:'HELD',paid:false,created:Date.now(),items:structuredClone(state.cart)});state.cart=[];save();toast('Pesanan disimpan dan dapat dilanjutkan dari daftar order');drawCart()}
  function bindPosDialogs(){document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelector('#productForm').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),p=state.products.find(x=>x.id===fd.get('id')),selected=fd.getAll('addon').map(id=>state.addons.find(a=>a.id===id)).filter(Boolean),large=fd.get('variant')==='Porsi besar'?4000:0;state.cart.push({productId:p.id,name:p.name,price:productPrice(p,'mataram')+large,qty:1,variant:fd.get('variant'),addons:selected.map(a=>a.name),addonTotal:selected.reduce((s,a)=>s+a.price,0),note:fd.get('note')});save();document.querySelector('#productDialog').close();drawCart();toast(p.name+' ditambahkan')};document.querySelectorAll('[data-table]').forEach(b=>b.onclick=()=>{state.selectedTable=b.dataset.table;save();document.querySelector('#tableDialog').close();renderPos()});const method=document.querySelector('#payMethod'),paid=document.querySelector('#paidAmount');method.onchange=()=>{document.querySelector('#cashField').classList.toggle('hidden',method.value!=='Tunai');document.querySelector('#changeInfo').classList.toggle('hidden',method.value!=='Tunai')};paid.oninput=()=>document.querySelector('#changeInfo').innerHTML='Kembalian: <b>'+rp(Math.max(0,Number(paid.value)-totalItems(state.cart)))+'</b>';document.querySelector('#paymentForm').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),total=totalItems(state.cart);if(fd.get('method')==='Tunai'&&Number(fd.get('paid'))<total){toast('Jumlah tunai masih kurang');return}document.querySelector('#paymentDialog').close();createOrder(true,fd.get('method'))}}
  function openPayment(){const total=totalItems(state.cart),d=document.querySelector('#paymentDialog'),paid=Math.ceil(total/10000)*10000;d.querySelector('#payTotal').textContent=rp(total);d.querySelector('#paidAmount').value=paid;d.querySelector('#changeInfo').innerHTML='Kembalian: <b>'+rp(paid-total)+'</b>';d.showModal()}
  function createOrder(paid,method){if(!state.cart.length)return;if(state.orderType==='DINE_IN'&&!state.selectedTable){toast('Pilih meja terlebih dahulu');return}const order={id:nextOrderId(),outlet_id:'mataram',table:state.orderType==='DINE_IN'?state.selectedTable:'Takeaway',type:state.orderType,status:'NEW',paid,method,created:Date.now(),items:structuredClone(state.cart)};state.orders.unshift(order);if(paid)recordTransaction(order,method);state.cart=[];save();toast('Order #'+order.id+' dikirim ke dapur');setTimeout(()=>location.href=paid?'receipt.html':'orders.html',450)}
  function recordTransaction(order,method){const total=totalItems(order.items),trx={id:'TRX-'+Date.now().toString().slice(-8),date:new Date().toISOString(),time:new Date().toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'}),outlet_id:order.outlet_id,cashier:'Siti Rahma',method,subtotal:total,discount:0,total,status:'Selesai',items:structuredClone(order.items)};state.transactions.unshift(trx);state.lastReceipt={...trx,order}}

  function renderOrders(){
    const all=[...state.heldOrders,...state.orders],tabs=[['all','Semua',all.length],['unpaid','Belum dibayar',state.orders.filter(o=>!o.paid).length],['done','Selesai',state.orders.filter(o=>o.status==='DONE').length],['held','Disimpan',state.heldOrders.length]];
    shell('cashier','Pesanan Aktif','Pantau progres dapur, lanjutkan pesanan tersimpan, dan selesaikan pembayaran.',`<div class="tabs">${tabs.map(([id,label,count])=>`<button class="tab ${state.orderTab===id?'active':''}" data-order-tab="${id}">${label} (${count})</button>`).join('')}</div><section class="card section-card"><div class="table-wrap"><table class="table"><thead><tr><th>Order</th><th>Meja / Tipe</th><th>Pesanan</th><th>Status</th><th>Pembayaran</th><th>Total</th><th></th></tr></thead><tbody id="orderRows"></tbody></table></div></section>${paymentDialog()}`,'<a class="btn btn-primary" href="pos.html">＋ Pesanan Baru</a>');
    const draw=()=>{const rows=state.orderTab==='held'?state.heldOrders:state.orderTab==='unpaid'?state.orders.filter(o=>!o.paid):state.orderTab==='done'?state.orders.filter(o=>o.status==='DONE'):all;document.querySelector('#orderRows').innerHTML=rows.map(o=>`<tr><td><strong>#${esc(o.id)}</strong><small>${Math.max(1,Math.floor((Date.now()-o.created)/60000))} menit lalu</small></td><td><strong>${esc(o.table)}</strong><small>${o.type==='DINE_IN'?'Dine In':'Takeaway'}</small></td><td>${o.items.reduce((s,i)=>s+i.qty,0)} item<small>${o.items.map(i=>esc(i.name)).join(', ')}</small></td><td>${badge(labelStatus(o.status))}</td><td>${badge(o.paid?'Lunas':o.status==='HELD'?'Belum dikirim':'Menunggu pembayaran')}</td><td><strong>${rp(totalItems(o.items))}</strong></td><td><div class="split-actions">${o.status==='HELD'?`<button class="btn btn-primary btn-sm" data-resume="${o.id}">Lanjutkan</button>`:!o.paid?`<button class="btn btn-primary btn-sm" data-pay-order="${o.id}">Bayar</button>`:''}<button class="btn btn-sm" data-order-detail="${o.id}" data-held="${o.status==='HELD'}">Detail</button></div></td></tr>`).join('')||'<tr><td colspan="7"><div class="empty">Tidak ada pesanan pada filter ini.</div></td></tr>';document.querySelectorAll('[data-resume]').forEach(b=>b.onclick=()=>resumeHeld(b.dataset.resume));document.querySelectorAll('[data-pay-order]').forEach(b=>b.onclick=()=>payExisting(b.dataset.payOrder));document.querySelectorAll('[data-order-detail]').forEach(b=>b.onclick=()=>orderDetail(b.dataset.orderDetail,b.dataset.held==='true'))};
    document.querySelectorAll('[data-order-tab]').forEach(b=>b.onclick=()=>{state.orderTab=b.dataset.orderTab;save();renderOrders()});draw();
  }
  function resumeHeld(id){const idx=state.heldOrders.findIndex(x=>x.id===id),order=state.heldOrders[idx];if(state.cart.length&&!confirm('Cart saat ini akan diganti dengan pesanan tersimpan. Lanjutkan?'))return;state.cart=structuredClone(order.items);state.orderType=order.type;state.selectedTable=order.table;state.heldOrders.splice(idx,1);save();location.href='pos.html'}
  function orderDetail(id,isHeld){const list=isHeld?state.heldOrders:state.orders,o=list.find(x=>x.id===id);const d=modal(`Order #${o.id}`,`<div class="detail-list"><div class="detail-row"><span>Meja / tipe</span><strong>${esc(o.table)} · ${o.type==='DINE_IN'?'Dine In':'Takeaway'}</strong></div><div class="detail-row"><span>Status</span><strong>${badge(labelStatus(o.status))}</strong></div>${o.items.map(i=>`<div class="detail-row"><span>${i.qty}× ${esc(i.name)}${i.addons.length?`<small style="display:block">+ ${i.addons.map(esc).join(', ')}</small>`:''}${i.note?`<small style="display:block">Catatan: ${esc(i.note)}</small>`:''}</span><strong>${rp((i.price+i.addonTotal)*i.qty)}</strong></div>`).join('')}<div class="detail-row"><span>Total</span><strong>${rp(totalItems(o.items))}</strong></div></div>`,`${isHeld?'<button class="btn btn-danger" id="cancelHeld">Batalkan pesanan</button>':''}<button class="btn" data-modal-close>Tutup</button>`);if(isHeld)d.querySelector('#cancelHeld').onclick=()=>{if(confirm('Batalkan pesanan tersimpan ini?')){state.heldOrders=state.heldOrders.filter(x=>x.id!==id);save();d.close();toast('Pesanan tersimpan dibatalkan');renderOrders()}}}
  function payExisting(id){const o=state.orders.find(x=>x.id===id),d=document.querySelector('#paymentDialog'),total=totalItems(o.items),suggested=Math.ceil(total/10000)*10000;d.querySelector('#payTotal').textContent=rp(total);d.querySelector('#paidAmount').value=suggested;d.querySelector('#changeInfo').innerHTML='Kembalian: <b>'+rp(suggested-total)+'</b>';d.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>d.close());d.querySelector('#payMethod').onchange=e=>{d.querySelector('#cashField').classList.toggle('hidden',e.target.value!=='Tunai');d.querySelector('#changeInfo').classList.toggle('hidden',e.target.value!=='Tunai')};d.querySelector('#paidAmount').oninput=e=>d.querySelector('#changeInfo').innerHTML='Kembalian: <b>'+rp(Math.max(0,Number(e.target.value)-total))+'</b>';d.querySelector('#paymentForm').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),method=fd.get('method');if(method==='Tunai'&&Number(fd.get('paid'))<total){toast('Jumlah tunai masih kurang');return}o.paid=true;o.method=method;recordTransaction(o,method);save();location.href='receipt.html'};d.showModal()}
  function renderReceipt(){const r=state.lastReceipt;if(!r){location.href='orders.html';return}document.body.innerHTML=`<main class="receipt-page"><div class="receipt-actions"><a class="btn btn-outline" href="orders.html">← Kembali</a><button class="btn btn-primary" id="printReceipt">Cetak Struk</button></div><article class="receipt"><div class="brand-mark">MN</div><h1>MIE AYAM NUSANTARA</h1><div class="receipt-center">Cabang ${esc(outletName(r.order.outlet_id))}<br>${esc(state.outlets.find(x=>x.id===r.order.outlet_id)?.address||'')}<br>Telp. ${esc(state.outlets.find(x=>x.id===r.order.outlet_id)?.phone||'-')}</div><div class="receipt-rule"></div><div class="receipt-row"><span>No.</span><span>${esc(r.id)}</span></div><div class="receipt-row"><span>Tanggal</span><span>${new Date(r.date).toLocaleDateString('id-ID')} ${esc(r.time)}</span></div><div class="receipt-row"><span>Kasir</span><span>Siti Rahma</span></div><div class="receipt-row"><span>Order</span><span>${esc(r.order.table)}</span></div><div class="receipt-rule"></div>${r.order.items.map(i=>`<div class="receipt-row"><span>${i.qty}x ${esc(i.name)}${i.addons.length?'<br>&nbsp;&nbsp;+'+i.addons.map(esc).join(', '):''}</span><span>${rp((i.price+(i.addonTotal||0))*i.qty)}</span></div>`).join('')}<div class="receipt-rule"></div><div class="receipt-row receipt-total"><span>TOTAL</span><span>${rp(r.total)}</span></div><div class="receipt-row"><span>${esc(r.method)}</span><span>LUNAS</span></div><div class="receipt-rule"></div><div class="receipt-thanks">Terima kasih sudah makan bersama kami!<br><b>Rasa hangat, hati dekat.</b></div></article></main>`;document.querySelector('#printReceipt').onclick=()=>window.print()}

  function renderKitchen(){const outlet=state.session?.outlet_id||'mataram',groups={NEW:[],PROCESSING:[],READY:[]};state.orders.filter(o=>o.outlet_id===outlet&&o.status!=='DONE').forEach(o=>(groups[o.status]||groups.NEW).push(o));document.body.innerHTML=`<main class="kds-page"><header class="kds-top"><a class="brand" href="${root}index.html"><b class="brand-mark">MN</b><span>Kitchen · ${esc(outletName(outlet))}</span></a><div class="kds-meta"><span class="live-dot">● Terhubung</span><span id="clock"></span><button class="btn btn-sm" id="kitchenActivity">Aktivitas</button></div></header><section class="kds-board">${kdsColumn('NEW','Pesanan Baru',groups.NEW,'Mulai Proses','PROCESSING')}${kdsColumn('PROCESSING','Sedang Diproses',groups.PROCESSING,'Tandai Selesai','READY')}${kdsColumn('READY','Siap Disajikan',groups.READY,'Pesanan Diambil','DONE')}</section></main>`;document.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{const o=state.orders.find(x=>x.id===b.dataset.id);o.status=b.dataset.status;state.notifications.unshift({id:uid('n'),title:`Order #${o.id} ${labelStatus(o.status)}`,text:`Status diperbarui oleh dapur ${outletName(outlet)}.`,read:false});save();renderKitchen();toast('Status #'+o.id+' diperbarui')});document.querySelector('#kitchenActivity').onclick=()=>modal('Aktivitas Dapur',`<div class="detail-list">${state.orders.filter(o=>o.outlet_id===outlet).slice(0,8).map(o=>`<div class="detail-row"><span>#${esc(o.id)} · ${esc(o.table)}</span><strong>${badge(labelStatus(o.status))}</strong></div>`).join('')}</div>`,`<button class="btn" data-modal-close>Tutup</button>`);const tick=()=>{const c=document.querySelector('#clock');if(c)c.textContent=new Date().toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit',second:'2-digit'})};tick();setInterval(tick,1000)}
  function kdsColumn(status,title,orders,button,next){return`<div class="kds-column"><div class="kds-col-head"><h2>${title}</h2><span class="count">${orders.length} order</span></div><div class="kds-list">${orders.length?orders.map(o=>`<article class="kds-card ${status==='PROCESSING'?'processing':status==='READY'?'ready':''}"><div class="kds-card-head"><h3>#${esc(o.id)}</h3><span class="timer">${Math.max(1,Math.floor((Date.now()-o.created)/60000))} menit</span></div><div class="kds-place">${esc(o.table)} · ${o.type==='DINE_IN'?'Dine In':'Takeaway'} · ${o.paid?'Lunas':'Belum bayar'}</div><div class="kds-items">${o.items.map(i=>`<div class="kds-item"><strong>${i.qty}×</strong><div><b>${esc(i.name)}</b>${i.addons?.length?`<div class="muted tiny">+ ${i.addons.map(esc).join(', ')}</div>`:''}</div></div>${i.note?`<div class="note">⚑ ${esc(i.note)}</div>`:''}`).join('')}</div><button class="btn ${status==='READY'?'btn-dark':'btn-primary'} btn-block" data-id="${o.id}" data-status="${next}">${button} →</button></article>`).join(''):'<div class="empty" style="color:#8f827a">Tidak ada order</div>'}</div></div>`}

  const routes={login:renderLogin,dashboard:renderDashboard,outlets:renderOutlets,products:renderProducts,inventory:renderInventory,reports:renderReports,users:renderUsers,shift:renderShift,pos:renderPos,orders:renderOrders,receipt:renderReceipt,kitchen:renderKitchen};
  (routes[page]||renderLogin)();
})();
